def check_solution(x, n=4):
    lhs = x**n + x

    # Check if LHS - 2 is a power of 2
    rhs_val = lhs - 2
    if rhs_val <= 0:
        return None

    # Check if rhs_val is a power of 2 (k must be a positive integer)
    k_candidate = 0
    temp = rhs_val
    while temp > 0:
        temp >>= 1
        k_candidate += 1

    if temp == 0 and rhs_val > 0:
        # k = k_candidate. Since rhs_val = 2^k, we need k = k_candidate
        return k_candidate
    else:
        return None

# Search for x > 4
X_MAX = 100
solutions = []

print(f"Starting search for n=4, x > 4, up to x={X_MAX}...")

for x in range(5, X_MAX + 1):
    k = check_solution(x)
    if k is not None:
        # Verify constraints: x > 4 (satisfied by loop), n=4 >= 2 (satisfied)
        # Also check against derived constraints for n=4:
        # 1. If x % 3 == 1, no solution (x=7, 10, 13, 16, ...)
        if x % 3 == 1:
            continue # Should not happen if check_solution is correct, but good check

        # 2. If x % 3 == 0 or x % 3 == 2, k must be even.
        if x % 3 == 0 or x % 3 == 2:
            if k % 2 != 0:
                continue

        solutions.append((x, 4, k))

print("Search complete.")
if solutions:
    print("Found solutions:")
    for sol in solutions:
        print(sol)
else:
    print("No solutions found in the search range.")

def is_power_of_two(n):
    if n <= 0:
        return False
    return (n & (n - 1) == 0)

def get_log2(n):
    if n <= 0 or not is_power_of_two(n):
        return None
    import math
    return int(math.log2(n))

def check_solutions_x_mult_3(X_limit=30):
    solutions_found = []
    # Start checking from x=6, multiples of 3
    for x in range(6, X_limit + 1, 3):
        print(f"--- Checking x = {x} (k must be even) ---")
        # Constraints: x > n >= 2
        for n in range(2, x):
            LHS_minus_2 = x**n + x - 2

            if is_power_of_two(LHS_minus_2):
                k = get_log2(LHS_minus_2)

                # Check constraints: k must be even
                if k is not None and k % 2 == 0:
                    solutions_found.append((x, n, k))
                    print(f"Found potential solution: ({x}, {n}, {k}). L.H.S = {x**n+x}, R.H.S = {2**k+2}")
                else:
                    print(f"LHS_minus_2 = {LHS_minus_2} = 2^{k}. k={k}. k is not even (or not integer).")
            # else:
            #     print(f"For n={n}, x={x}: x^n + x - 2 = {LHS_minus_2} (Not a power of 2)")
    return solutions_found

solutions = check_solutions_x_mult_3(X_limit=30)
print("\nFinal solutions found for x=3m up to x=30:", solutions)

